package run.ikaros.password; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException; @Service public class PasswordVaultService{private final PasswordVaultRepository vaults;private final PasswordVaultItemRepository items;public PasswordVaultService(PasswordVaultRepository v,PasswordVaultItemRepository i){vaults=v;items=i;}public Mono<PasswordVaultView> create(UUID a,CreatePasswordVaultRequest q){Instant n=Instant.now();return vaults.save(new PasswordVaultEntity(null,a,q.name().trim(),"USER_LOCKED_E2EE",q.cryptoContext(),q.encryptedRecoveryKey(),PasswordVaultStatus.LOCKED,n,n,null)).map(this::vault);}public Flux<PasswordVaultView> list(UUID a){return vaults.findAllByOwnerIdOrderByCreatedAtDesc(a).map(this::vault);}public Mono<PasswordVaultView> setStatus(UUID a,UUID id,PasswordVaultStatus status){return own(a,id).flatMap(v->vaults.save(new PasswordVaultEntity(v.id(),v.ownerId(),v.name(),v.securityProfile(),v.cryptoContext(),v.encryptedRecoveryKey(),status,v.createdAt(),Instant.now(),v.version()))).map(this::vault);}public Mono<PasswordVaultItemView> createItem(UUID a,UUID v,UpsertVaultItemRequest q){return unlocked(a,v).flatMap(x->items.save(new PasswordVaultItemEntity(null,v,a,q.itemType(),q.encryptedName(),q.encryptedPayload(),q.encryptedCustomFields(),q.favorite(),1,false,Instant.now(),Instant.now(),null))).map(this::item);}public Flux<PasswordVaultItemView> listItems(UUID a,UUID v){return unlocked(a,v).flatMapMany(x->items.findAllByVaultIdAndOwnerIdAndTombstoneFalseOrderByUpdatedAtDesc(v,a).map(this::item));}public Mono<PasswordVaultItemView> updateItem(UUID a,UUID id,UpsertVaultItemRequest q){return items.findById(id).filter(i->i.ownerId().equals(a)&&!i.tombstone()).switchIfEmpty(Mono.error(new NotFoundException("Vault Item 不存在或无权访问"))).flatMap(i->unlocked(a,i.vaultId()).flatMap(v->{if(i.revision()!=q.expectedRevision())return Mono.error(new ConflictException("Vault Item Revision 冲突"));return items.save(new PasswordVaultItemEntity(i.id(),i.vaultId(),i.ownerId(),q.itemType(),q.encryptedName(),q.encryptedPayload(),q.encryptedCustomFields(),q.favorite(),i.revision()+1,false,i.createdAt(),Instant.now(),i.version()));})).map(this::item);}public Mono<PasswordVaultItemView> deleteItem(UUID a,UUID id){return items.findById(id).filter(i->i.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Vault Item 不存在或无权访问"))).flatMap(i->unlocked(a,i.vaultId()).flatMap(v->items.save(new PasswordVaultItemEntity(i.id(),i.vaultId(),i.ownerId(),i.itemType(),i.encryptedName(),i.encryptedPayload(),i.encryptedCustomFields(),i.favorite(),i.revision()+1,true,i.createdAt(),Instant.now(),i.version())))).map(this::item);}private Mono<PasswordVaultEntity> own(UUID a,UUID id){return vaults.findById(id).filter(v->v.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Password Vault 不存在或无权访问")));}private Mono<PasswordVaultEntity> unlocked(UUID a,UUID id){return own(a,id).flatMap(v->v.status()==PasswordVaultStatus.UNLOCKED?Mono.just(v):Mono.error(new ConflictException("Password Vault 尚未解锁")));}private PasswordVaultView vault(PasswordVaultEntity v){return new PasswordVaultView(v.id(),v.ownerId(),v.name(),v.securityProfile(),v.cryptoContext(),v.status(),v.createdAt());}private PasswordVaultItemView item(PasswordVaultItemEntity i){return new PasswordVaultItemView(i.id(),i.vaultId(),i.itemType(),i.encryptedName(),i.encryptedPayload(),i.encryptedCustomFields(),i.favorite(),i.revision(),i.tombstone(),i.createdAt(),i.updatedAt());}}
